public void init()
{

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        Set concurrencyModeEnumSet = new Set(Types::Enum);

        concurrencyModeEnumSet.add(RetailDiscountConcurrency::AlwaysApply);
        concurrencyModeEnumSet.add(RetailDiscountConcurrency::BestPrice);
        concurrencyModeEnumSet.add(RetailDiscountConcurrency::Compounded);
        concurrencyModeEnumSet.add(RetailDiscountConcurrency::Exclusive);

        sysFormEnumComboBox::newParameters(this, this.controlId(formControlStr(RetailPriceAdjustments, Concurrency_ConcurrencyMode)), enumNum(RetailDiscountConcurrency), concurrencyModeEnumSet);
    }

    next init();

}
